def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    if not history:
        return [0.0] * horizon
    y = [float(v) if math.isfinite(float(v)) else 0.0 for v in history]
    n = len(y)
    best = None
    for mode in ('identity', 'sqrt', 'log'):
        if mode == 'log' and min(y[max(0,n-64):]) <= 0.0:
            continue
        for w in (16, 24, 32, 48, 64):
            if w > n:
                continue
            q = max(4, min(12, w // 4))
            train = w - q
            vals = y[n-w:]
            if mode == 'identity':
                z = vals
            elif mode == 'sqrt':
                z = [math.sqrt(max(0.0, v)) for v in vals]
            else:
                z = [math.log(max(v, 1e-12)) for v in vals]
            sx = train * (train - 1) / 2.0
            sxx = train * (train - 1) * (2 * train - 1) / 6.0
            sz = sum(z[:train])
            sxz = sum(i * z[i] for i in range(train))
            den = train * sxx - sx * sx
            slope = (train * sxz - sx * sz) / den if den else 0.0
            intercept = (sz - slope * sx) / train
            err = 0.0
            for i in range(train, w):
                t = intercept + slope * i
                if mode == 'identity':
                    pred = t
                elif mode == 'sqrt':
                    pred = max(0.0, t) ** 2
                else:
                    pred = math.exp(max(-700.0, min(700.0, t)))
                err += abs(pred-vals[i])/(abs(pred)+abs(vals[i])+1e-9)
            score = err/q
            if best is None or score < best[0]:
                best = (score, mode, w)
    if best is None:
        return [y[-1]] * horizon
    _, mode, w = best
    vals = y[-w:]
    if mode == 'identity':
        z = vals
    elif mode == 'sqrt':
        z = [math.sqrt(max(0.0, v)) for v in vals]
    else:
        z = [math.log(max(v, 1e-12)) for v in vals]
    sx = w*(w-1)/2.0
    sxx = w*(w-1)*(2*w-1)/6.0
    sz = sum(z)
    sxz = sum(i*z[i] for i in range(w))
    den = w*sxx-sx*sx
    slope = (w*sxz-sx*sz)/den if den else 0.0
    intercept = (sz-slope*sx)/w
    out = []
    for k in range(horizon):
        t = intercept+slope*(w+k)
        if mode == 'identity':
            value = t
        elif mode == 'sqrt':
            value = max(0.0,t)**2
        else:
            value = math.exp(max(-700.0,min(700.0,t)))
        out.append(value if math.isfinite(value) else y[-1])
    return out
